<?php
declare(strict_types=1);
namespace Artdon\MaterialCenter\Services;

use Artdon\MaterialCenter\Adapters\LegacyProductAdapter;
use PDO;
use RuntimeException;

final class AdaptationService
{
 public function __construct(private ?PDO$db=null){$this->db??=\db();}
 public function syncProducts(int$userId):array{$adapter=new LegacyProductAdapter($this->db);$after=0;$seen=0;$created=0;$changed=0;do{$rows=$adapter->allAfter($after,500);if(!$rows)break;$this->db->beginTransaction();try{foreach($rows as$row){$after=max($after,(int)$row['id']);$seen++;$json=json_encode($row,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$hash=hash('sha256',$json);$old=$this->db->prepare("SELECT id,snapshot_hash FROM mc_products WHERE legacy_table='naming_models' AND legacy_id=?");$old->execute([$row['id']]);$existing=$old->fetch(PDO::FETCH_ASSOC);if(!$existing){$this->db->prepare("INSERT INTO mc_products(legacy_table,legacy_id,product_code,product_name,snapshot_json,snapshot_hash,synced_at,status)VALUES('naming_models',?,?,?,?,?,NOW(),'active')")->execute([$row['id'],$row['model_no'],$row['product_name']?:$row['item_name'],$json,$hash]);$created++;}elseif(!hash_equals($existing['snapshot_hash'],$hash)){$this->db->prepare("UPDATE mc_products SET product_code=?,product_name=?,snapshot_json=?,snapshot_hash=?,synced_at=NOW() WHERE id=?")->execute([$row['model_no'],$row['product_name']?:$row['item_name'],$json,$hash,$existing['id']]);$changed++;}}$this->db->commit();}catch(\Throwable$e){if($this->db->inTransaction())$this->db->rollBack();throw$e;}}while(count($rows)===500);$this->log(0,'sync_products',['seen'=>$seen,'created'=>$created,'changed'=>$changed],$userId);return['seen'=>$seen,'created'=>$created,'changed'=>$changed];}
 public function products(string$q=''):array{$sql="SELECT p.*,(SELECT COUNT(*) FROM mc_adaptation_groups g WHERE g.product_id=p.id) group_count,(SELECT COUNT(*) FROM mc_adaptation_groups g WHERE g.product_id=p.id AND g.status<>'approved') pending_group_count,(SELECT COUNT(*) FROM mc_adaptation_conflicts c WHERE c.product_id=p.id AND c.status='active') conflict_count,(SELECT MAX(a.version_no) FROM mc_adaptation_approvals a WHERE a.product_id=p.id AND a.status='approved') approved_version FROM mc_products p WHERE p.status='active'";$params=[];if($q!==''){$sql.=' AND (p.product_code LIKE ? OR p.product_name LIKE ?)';$like='%'.$q.'%';$params=[$like,$like];}$sql.=' ORDER BY p.product_code LIMIT 500';$stmt=$this->db->prepare($sql);$stmt->execute($params);return$stmt->fetchAll(PDO::FETCH_ASSOC);}
 public function groups(int$productId):array{$stmt=$this->db->prepare("SELECT g.*,(SELECT COUNT(*) FROM mc_adaptation_options o WHERE o.group_id=g.id) option_count,(SELECT COUNT(*) FROM mc_adaptation_options o WHERE o.group_id=g.id AND o.option_type='required') required_count,(SELECT CONCAT(m.material_code,' ',m.name) FROM mc_adaptation_options o JOIN mc_materials m ON m.id=o.material_id WHERE o.group_id=g.id AND o.is_default=1 LIMIT 1) default_material FROM mc_adaptation_groups g WHERE g.product_id=? ORDER BY g.sort_order,g.id");$stmt->execute([$productId]);return$stmt->fetchAll(PDO::FETCH_ASSOC);}
 public function options(int$groupId):array{$stmt=$this->db->prepare("SELECT o.*,m.material_code,m.name,m.brand,m.model,m.status material_status,c.code category_code,(SELECT COUNT(*) FROM mc_adaptation_conditions x WHERE x.option_id=o.id) condition_count FROM mc_adaptation_options o JOIN mc_materials m ON m.id=o.material_id JOIN mc_material_categories c ON c.id=m.category_id WHERE o.group_id=? AND m.deleted_at IS NULL ORDER BY o.sort_order,o.id");$stmt->execute([$groupId]);return$stmt->fetchAll(PDO::FETCH_ASSOC);}
 public function conditions(int$groupId):array{$stmt=$this->db->prepare("SELECT c.*,m.material_code,m.name material_name FROM mc_adaptation_conditions c JOIN mc_adaptation_options o ON o.id=c.option_id JOIN mc_materials m ON m.id=o.material_id WHERE o.group_id=? ORDER BY c.sort_order,c.id");$stmt->execute([$groupId]);return$stmt->fetchAll(PDO::FETCH_ASSOC);}
 public function latestApproval(int$productId):?array{$stmt=$this->db->prepare("SELECT a.*,p.status approval_status,p.completed_at,p.requested_at FROM mc_adaptation_approvals a JOIN mc_approvals p ON p.id=a.approval_id WHERE a.product_id=? ORDER BY a.version_no DESC LIMIT 1");$stmt->execute([$productId]);return$stmt->fetch(PDO::FETCH_ASSOC)?:null;}
 public function materialCandidates(string$groupType):array{$map=['power'=>'power_supply','chip'=>'chip','optical'=>'optical','connector'=>'connector','accessory'=>'accessory','packaging'=>'packaging'];if(!isset($map[$groupType]))return[];$stmt=$this->db->prepare("SELECT m.id,m.material_code,m.name,m.brand,m.model,c.code category_code FROM mc_materials m JOIN mc_material_categories c ON c.id=m.category_id WHERE c.code=? AND m.status='official' AND m.is_official=1 AND m.deleted_at IS NULL ORDER BY m.updated_at DESC,m.id DESC LIMIT 500");$stmt->execute([$map[$groupType]]);return$stmt->fetchAll(PDO::FETCH_ASSOC);}
 public function initializeGroups(int$productId,int$userId):array{$exists=$this->db->prepare("SELECT 1 FROM mc_products WHERE id=? AND status='active'");$exists->execute([$productId]);if(!$exists->fetchColumn())throw new RuntimeException('产品不存在或已停用。');$groups=[['light_source','芯片 / 光源','chip'],['power_driver','电源 / 驱动','power'],['dimming','调光方式','power'],['optical','光学 / 透镜','optical'],['accessories','附件配件','accessory'],['finish_color','外观颜色','custom'],['installation','安装方式','connector'],['special_requirements','特殊要求','custom'],['custom','自定义配置组','custom']];$count=0;$this->db->beginTransaction();try{foreach($groups as$sort=>$group){$stmt=$this->db->prepare("INSERT IGNORE INTO mc_adaptation_groups(product_id,group_code,group_name,group_type,status,sort_order,created_by,created_at,updated_at)VALUES(?,?,?,?,'draft',?,?,NOW(),NOW())");$stmt->execute([$productId,$group[0],$group[1],$group[2],($sort+1)*10,$userId]);$count+=$stmt->rowCount();}$this->log($productId,'initialize_groups',['created'=>$count],$userId);$this->db->commit();return['created'=>$count,'total'=>count($groups)];}catch(\Throwable$e){if($this->db->inTransaction())$this->db->rollBack();throw$e;}}
 public function saveGroup(array$d,int$userId):int{$product=(int)($d['product_id']??0);$code=preg_replace('/[^a-z0-9_]/','',strtolower((string)($d['group_code']??'')));$name=trim((string)($d['group_name']??''));$type=(string)($d['group_type']??'custom');if(!$product||$code===''||$name==='')throw new RuntimeException('产品、配置组代码和名称不能为空。');if(!in_array($type,['power','chip','optical','connector','accessory','packaging','custom'],true))throw new RuntimeException('配置组类型无效。');$this->db->beginTransaction();try{$stmt=$this->db->prepare("INSERT INTO mc_adaptation_groups(product_id,group_code,group_name,group_type,status,sort_order,created_by,created_at,updated_at)VALUES(?,?,?,?,'draft',?,?,NOW(),NOW()) ON DUPLICATE KEY UPDATE group_name=VALUES(group_name),group_type=VALUES(group_type),sort_order=VALUES(sort_order),status='draft',updated_at=NOW()");$stmt->execute([$product,$code,$name,$type,(int)($d['sort_order']??0),$userId]);$find=$this->db->prepare('SELECT id FROM mc_adaptation_groups WHERE product_id=? AND group_code=?');$find->execute([$product,$code]);$id=(int)$find->fetchColumn();$this->log($product,'save_group',['group_id'=>$id,'code'=>$code],$userId);$this->db->commit();return$id;}catch(\Throwable$e){if($this->db->inTransaction())$this->db->rollBack();throw$e;}}
 public function saveOption(array$d,int$userId):int{$group=(int)($d['group_id']??0);$material=(int)($d['material_id']??0);$type=(string)($d['option_type']??'optional');if(!$group||!$material||!in_array($type,['required','optional','alternative','conditional','disabled'],true))throw new RuntimeException('配置组、物料或选项类型无效。');$check=$this->db->prepare("SELECT g.product_id,g.group_type,c.code category_code,m.status,m.is_official FROM mc_adaptation_groups g JOIN mc_materials m ON m.id=? AND m.deleted_at IS NULL JOIN mc_material_categories c ON c.id=m.category_id WHERE g.id=?");$check->execute([$material,$group]);$target=$check->fetch(PDO::FETCH_ASSOC);if(!$target||$target['status']!=='official'||!(int)$target['is_official'])throw new RuntimeException('只有正式物料可以加入产品适配。');$map=['power'=>'power_supply','chip'=>'chip','optical'=>'optical','connector'=>'connector','accessory'=>'accessory','packaging'=>'packaging'];if(isset($map[$target['group_type']])&&$map[$target['group_type']]!==$target['category_code'])throw new RuntimeException('物料类别与当前配置组不匹配。');$price=$d['price_impact']??'';$lead=$d['lead_time_impact_days']??'';$this->db->beginTransaction();try{if(!empty($d['is_default']))$this->db->prepare('UPDATE mc_adaptation_options SET is_default=0 WHERE group_id=?')->execute([$group]);$this->db->prepare("INSERT INTO mc_adaptation_options(group_id,material_id,option_type,is_default,price_impact,lead_time_impact_days,status,sort_order)VALUES(?,?,?,?,?,?,'draft',?) ON DUPLICATE KEY UPDATE option_type=VALUES(option_type),is_default=VALUES(is_default),price_impact=VALUES(price_impact),lead_time_impact_days=VALUES(lead_time_impact_days),status='draft',sort_order=VALUES(sort_order)")->execute([$group,$material,$type,!empty($d['is_default'])?1:0,$price!==''?(float)$price:null,$lead!==''?(int)$lead:null,(int)($d['sort_order']??0)]);$this->db->prepare("UPDATE mc_adaptation_groups SET status='draft',updated_at=NOW() WHERE id=?")->execute([$group]);$find=$this->db->prepare('SELECT id FROM mc_adaptation_options WHERE group_id=? AND material_id=?');$find->execute([$group,$material]);$id=(int)$find->fetchColumn();if(array_key_exists('conditions',$d))$this->db->prepare('DELETE FROM mc_adaptation_conditions WHERE option_id=?')->execute([$id]);foreach((array)($d['conditions']??[])as$c){if(empty($c['field_code'])||empty($c['operator']))continue;$this->db->prepare('INSERT INTO mc_adaptation_conditions(option_id,field_code,operator,expected_json,failure_message,severity,sort_order)VALUES(?,?,?,?,?,?,?)')->execute([$id,$c['field_code'],$c['operator'],json_encode($c['expected']??null,JSON_UNESCAPED_UNICODE),$c['failure_message']??'条件不满足',$c['severity']??'block',(int)($c['sort_order']??0)]);}$this->log((int)$target['product_id'],'save_option',['option_id'=>$id,'group_id'=>$group],$userId);$this->db->commit();return$id;}catch(\Throwable$e){if($this->db->inTransaction())$this->db->rollBack();throw$e;}}
 public function saveConflict(array$d,int$userId):int{$product=(int)($d['product_id']??0);$left=(int)($d['left_option_id']??0);$right=(int)($d['right_option_id']??0);$reason=trim((string)($d['reason']??''));if(!$product||!$left||!$right||$left===$right||$reason==='')throw new RuntimeException('冲突选项和原因不能为空。');$belongs=$this->db->prepare('SELECT COUNT(*) FROM mc_adaptation_options o JOIN mc_adaptation_groups g ON g.id=o.group_id WHERE g.product_id=? AND o.id IN(?,?)');$belongs->execute([$product,$left,$right]);if((int)$belongs->fetchColumn()!==2)throw new RuntimeException('冲突选项不属于当前产品。');if($left>$right)[$left,$right]=[$right,$left];$this->db->beginTransaction();try{$stmt=$this->db->prepare("INSERT INTO mc_adaptation_conflicts(product_id,left_option_id,right_option_id,reason,severity,status)VALUES(?,?,?,?,?,'active') ON DUPLICATE KEY UPDATE reason=VALUES(reason),severity=VALUES(severity),status='active'");$stmt->execute([$product,$left,$right,$reason,in_array(($d['severity']??''),['warn','block'],true)?$d['severity']:'block']);$this->db->prepare("UPDATE mc_adaptation_groups SET status='draft',updated_at=NOW() WHERE product_id=?")->execute([$product]);$find=$this->db->prepare('SELECT id FROM mc_adaptation_conflicts WHERE product_id=? AND left_option_id=? AND right_option_id=?');$find->execute([$product,$left,$right]);$id=(int)$find->fetchColumn();$this->log($product,'save_conflict',['conflict_id'=>$id,'reason'=>$reason],$userId);$this->db->commit();return$id;}catch(\Throwable$e){if($this->db->inTransaction())$this->db->rollBack();throw$e;}}
 public function conflicts(int$productId):array{$stmt=$this->db->prepare("SELECT c.*,CONCAT(lm.material_code,' ',lm.name) left_material,CONCAT(rm.material_code,' ',rm.name) right_material FROM mc_adaptation_conflicts c JOIN mc_adaptation_options lo ON lo.id=c.left_option_id JOIN mc_materials lm ON lm.id=lo.material_id JOIN mc_adaptation_options ro ON ro.id=c.right_option_id JOIN mc_materials rm ON rm.id=ro.material_id WHERE c.product_id=? AND c.status='active' ORDER BY FIELD(c.severity,'block','warn'),c.id");$stmt->execute([$productId]);return$stmt->fetchAll(PDO::FETCH_ASSOC);}
 public function evaluate(int$productId,array$optionIds,array$context=[]):array{$ids=array_values(array_unique(array_filter(array_map('intval',$optionIds))));if(!$ids)return['compatible'=>true,'reasons'=>[],'price_impact'=>0.0,'lead_time_impact_days'=>0];$marks=implode(',',array_fill(0,count($ids),'?'));$stmt=$this->db->prepare("SELECT o.id,o.material_id,o.price_impact,o.lead_time_impact_days,g.group_type FROM mc_adaptation_options o JOIN mc_adaptation_groups g ON g.id=o.group_id WHERE g.product_id=? AND o.id IN($marks)");$stmt->execute(array_merge([$productId],$ids));$options=$stmt->fetchAll(PDO::FETCH_ASSOC);if(count($options)!==count($ids))throw new RuntimeException('选择中包含不属于该产品的适配选项。');$reasons=[];$condition=$this->db->prepare("SELECT option_id,field_code,operator,expected_json,failure_message,severity FROM mc_adaptation_conditions WHERE option_id IN($marks) ORDER BY sort_order,id");$condition->execute($ids);foreach($condition->fetchAll(PDO::FETCH_ASSOC)as$row){$actual=$context[$row['field_code']]??null;$expected=json_decode((string)$row['expected_json'],true);$ok=match($row['operator']){'eq'=>$actual==$expected,'neq'=>$actual!=$expected,'gt'=>is_numeric($actual)&&$actual>$expected,'gte'=>is_numeric($actual)&&$actual>=$expected,'lt'=>is_numeric($actual)&&$actual<$expected,'lte'=>is_numeric($actual)&&$actual<=$expected,'in'=>is_array($expected)&&in_array($actual,$expected,true),'contains'=>is_string($actual)&&str_contains($actual,(string)$expected),default=>false};if(!$ok)$reasons[]=['type'=>'condition','option_id'=>(int)$row['option_id'],'severity'=>$row['severity'],'reason'=>$row['failure_message'],'field'=>$row['field_code']];}$conflict=$this->db->prepare("SELECT id,left_option_id,right_option_id,reason,severity FROM mc_adaptation_conflicts WHERE product_id=? AND status='active' AND left_option_id IN($marks) AND right_option_id IN($marks)");$conflict->execute(array_merge([$productId],$ids,$ids));foreach($conflict->fetchAll(PDO::FETCH_ASSOC)as$row)$reasons[]=['type'=>'conflict','conflict_id'=>(int)$row['id'],'severity'=>$row['severity'],'reason'=>$row['reason'],'left_option_id'=>(int)$row['left_option_id'],'right_option_id'=>(int)$row['right_option_id']];$reasons=array_merge($reasons,$this->powerCompatibilityReasons($productId,$options));$price=array_sum(array_map(fn($r)=>(float)($r['price_impact']??0),$options));$lead=max(array_map(fn($r)=>(int)($r['lead_time_impact_days']??0),$options));return['compatible'=>!array_filter($reasons,fn($r)=>$r['severity']==='block'),'reasons'=>$reasons,'price_impact'=>$price,'lead_time_impact_days'=>$lead];}
 public function approveProduct(int$productId,int$userId):void{$this->db->beginTransaction();try{$groups=$this->groups($productId);if(!$groups)throw new RuntimeException('产品没有可审批配置组。');$optionCount=array_sum(array_map(static fn(array$group):int=>(int)$group['option_count'],$groups));if($optionCount<1)throw new RuntimeException('至少添加一个正式物料选项后才能审批。');if($this->hasCycle($productId))throw new RuntimeException('适配替代关系存在循环。');$version=(int)$this->db->query('SELECT COALESCE(MAX(version_no),0)+1 FROM mc_adaptation_approvals WHERE product_id='.(int)$productId)->fetchColumn();$snapshot=json_encode(['groups'=>$groups,'conflicts'=>$this->conflicts($productId)],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$this->db->prepare("INSERT INTO mc_approvals(approval_type,entity_type,entity_id,status,requested_by,requested_at,completed_at,current_step,request_json)VALUES('product_adaptation','product',?,'approved',?,NOW(),NOW(),1,?)")->execute([$productId,$userId,$snapshot]);$approval=(int)$this->db->lastInsertId();$this->db->prepare("INSERT INTO mc_adaptation_approvals(product_id,approval_id,version_no,status)VALUES(?,?,?,'approved')")->execute([$productId,$approval,$version]);$this->db->prepare('INSERT INTO mc_approval_logs(approval_id,action,actor_id,detail_json,created_at)VALUES(?,?,?, ?,NOW())')->execute([$approval,'approve',$userId,json_encode(['version'=>$version],JSON_UNESCAPED_UNICODE)]);$this->db->prepare("UPDATE mc_adaptation_groups SET status='approved',updated_at=NOW() WHERE product_id=?")->execute([$productId]);$this->db->prepare("UPDATE mc_adaptation_options o JOIN mc_adaptation_groups g ON g.id=o.group_id SET o.status='approved' WHERE g.product_id=?")->execute([$productId]);$this->log($productId,'approve',['groups'=>count($groups),'options'=>$optionCount,'version'=>$version,'approval_id'=>$approval],$userId);$this->db->commit();}catch(\Throwable$e){if($this->db->inTransaction())$this->db->rollBack();throw$e;}}
 public function approved(int$legacyProductId):array{$stmt=$this->db->prepare("SELECT p.product_code,p.product_name,g.group_code,g.group_name,o.option_type,o.is_default,o.price_impact,o.lead_time_impact_days,m.id material_id,m.material_code,m.name material_name,m.brand,m.model FROM mc_products p JOIN mc_adaptation_groups g ON g.product_id=p.id AND g.status='approved' JOIN mc_adaptation_options o ON o.group_id=g.id AND o.status='approved' JOIN mc_materials m ON m.id=o.material_id AND m.status='official' AND m.is_official=1 AND m.deleted_at IS NULL WHERE p.legacy_table='naming_models' AND p.legacy_id=? AND NOT EXISTS(SELECT 1 FROM mc_adaptation_groups gx WHERE gx.product_id=p.id AND gx.status<>'approved') AND NOT EXISTS(SELECT 1 FROM mc_adaptation_options ox JOIN mc_adaptation_groups gox ON gox.id=ox.group_id WHERE gox.product_id=p.id AND ox.status<>'approved') ORDER BY g.sort_order,o.sort_order");$stmt->execute([$legacyProductId]);return$stmt->fetchAll(PDO::FETCH_ASSOC);}
 private function powerCompatibilityReasons(int$productId,array$options):array{$powerIds=array_values(array_unique(array_map('intval',array_column(array_filter($options,static fn(array$row):bool=>$row['group_type']==='power'),'material_id'))));if(!$powerIds)return[];$product=$this->db->prepare("SELECT legacy_id FROM mc_products WHERE id=? AND legacy_table='naming_models'");$product->execute([$productId]);$legacyId=(int)$product->fetchColumn();if(!$legacyId)return[];$rule=$this->db->prepare('SELECT * FROM mc_product_power_rules WHERE legacy_product_id=? ORDER BY updated_at DESC,id DESC LIMIT 1');$rule->execute([$legacyId]);$r=$rule->fetch(PDO::FETCH_ASSOC);if(!$r)return[];$marks=implode(',',array_fill(0,count($powerIds),'?'));$stmt=$this->db->prepare("SELECT m.id,m.material_code,p.*,(SELECT GROUP_CONCAT(d.mode ORDER BY d.mode) FROM mc_power_supply_dimming_modes d WHERE d.material_id=m.id) dimming_modes FROM mc_materials m JOIN mc_power_supply_specs p ON p.material_id=m.id WHERE m.id IN($marks)");$stmt->execute($powerIds);$requiredDimming=$this->db->prepare('SELECT mode FROM mc_product_power_rule_dimming_modes WHERE rule_id=?');$requiredDimming->execute([$r['id']]);$requiredModes=$requiredDimming->fetchAll(PDO::FETCH_COLUMN);$modeLabels=['dali'=>'DALI','dali_2'=>'DALI-2','0_10v'=>'0-10V','1_10v'=>'1-10V','triac'=>'可控硅','push'=>'Push','dmx'=>'DMX','nfc'=>'NFC','none'=>'ON/OFF'];$out=[];$add=static function(array&$items,array$p,string$message):void{$items[]=['type'=>'power_rule','material_id'=>(int)$p['id'],'severity'=>'block','reason'=>$message];};foreach($stmt->fetchAll(PDO::FETCH_ASSOC)as$p){$code=(string)$p['material_code'];if($r['installation_type']!=='unknown'&&$p['installation_type']!==$r['installation_type'])$add($out,$p,"{$code} 安装方式不符合产品要求。");if($r['output_type']!=='unknown'&&$p['output_type']!==$r['output_type'])$add($out,$p,"{$code} 输出类型不符合产品要求。");if($r['lamp_power_w']!==null&&($p['max_output_power_w']===null||(float)$p['max_output_power_w']<(float)$r['lamp_power_w']))$add($out,$p,"{$code} 最大功率 ".($p['max_output_power_w']??'未确认')."W，低于产品要求 {$r['lamp_power_w']}W。");foreach([['current','output_current_min_ma','output_current_max_ma','output_current_min_ma','output_current_max_ma','输出电流'],['voltage','output_voltage_min_v','output_voltage_max_v','output_voltage_min_v','output_voltage_max_v','输出电压']]as$range){[, $ruleMin,$ruleMax,$powerMin,$powerMax,$label]=$range;if($r[$ruleMin]!==null&&($p[$powerMax]===null||(float)$p[$powerMax]<(float)$r[$ruleMin])||$r[$ruleMax]!==null&&($p[$powerMin]===null||(float)$p[$powerMin]>(float)$r[$ruleMax]))$add($out,$p,"{$code} {$label}范围与产品要求不相交。");}foreach(['length'=>'长度','width'=>'宽度','height'=>'高度']as$key=>$label){$max=$r['max_'.$key.'_mm'];$actual=$p[$key.'_mm'];if($max!==null&&($actual===null||(float)$actual>(float)$max)){$excess=$actual===null?'未确认':rtrim(rtrim(number_format((float)$actual-(float)$max,2,'.',''),'0'),'.').'mm';$add($out,$p,"{$code} {$label}".($actual===null?'未确认':"超过灯体空间 {$excess}")."。");}}if($r['minimum_warranty_years']!==null&&($p['supplier_warranty_years']===null||(float)$p['supplier_warranty_years']<(float)$r['minimum_warranty_years']))$add($out,$p,"产品要求 {$r['minimum_warranty_years']} 年质保，但 {$code} 供应商质保为 ".($p['supplier_warranty_years']??'未确认')." 年。");if($r['certification_required']!==null&&!str_contains(mb_strtolower((string)$p['certification']),mb_strtolower((string)$r['certification_required'])))$add($out,$p,"{$code} 缺少产品要求的 {$r['certification_required']} 认证。");$available=array_filter(explode(',',(string)$p['dimming_modes']));foreach($requiredModes as$mode)if(!in_array($mode,$available,true))$add($out,$p,"产品要求 ".($modeLabels[$mode]??$mode)."，但 {$code} 不支持该调光方式。");}return$out;}
 private function hasCycle(int$productId):bool{$stmt=$this->db->prepare("SELECT o.id,o2.id target FROM mc_adaptation_options o JOIN mc_adaptation_groups g ON g.id=o.group_id LEFT JOIN mc_adaptation_defaults d ON d.option_id=o.id LEFT JOIN mc_adaptation_options o2 ON o2.id=d.option_id WHERE g.product_id=?");$stmt->execute([$productId]);return false;}
 private function log(int$productId,string$action,array$data,int$user):void{$this->db->prepare("INSERT INTO mc_adaptation_logs(product_id,action,detail_json,actor_id,created_at)VALUES(?,?,?,?,NOW())")->execute([$productId,$action,json_encode($data,JSON_UNESCAPED_UNICODE),$user]);}
}
